-- M15.01–02; 24 original teacher-authored Y1 questions. Based on the source-backed M15 theory,
-- cross-checked with Drive 'Pedagogik mahorat to'plam 2025' (induction, reflection, methods).
-- Not historical exam transcripts. Run only after separate production authorization.
BEGIN;
DO $m15$
DECLARE r record; v_lesson uuid; v_con uuid; v_sub uuid; v_group text; v_qid uuid; v_oid uuid; v_choices text[]; v_n integer; v_seed text;
BEGIN
 FOR r IN SELECT * FROM (VALUES
(1,1,'Pedagogika didaktikadan nimasi bilan farqlanadi?','Pedagogika ta’lim-tarbiyani, didaktika ta’lim jarayonini o‘rganadi','Pedagogika faqat bilishni, didaktika faqat xulqni o‘rganadi','Pedagogika faqat boshqaruvni, didaktika faqat nazoratni o‘rganadi','Pedagogika faqat yoshni, didaktika faqat tartibni o‘rganadi','Didaktika pedagogikaning ta’lim nazariyasiga oid bo‘limidir','bilish'),
(1,2,'Amaliy harakat ko‘p takrorlanib avtomatik bajarila boshladi. Bu nima?','Malaka — avtomatlashib mustahkamlangan amaliy ko‘nikma','Bilim — yangi ma’lumotning faqat og‘zaki bayoni','Qiziqish — mavzuga bo‘lgan hissiy munosabat','Motivatsiya — faoliyat boshlashga undovchi sabab','Malaka ko‘nikmaning mashq orqali avtomatlashgan ko‘rinishidir','bilish'),
(1,3,'O‘quvchi qoidani yangi vaziyatga qo‘lladi. Asosiy natija qaysi?','Bilimdan foydalanish ko‘nikmasi amalda namoyon bo‘ldi','Faqat tayyor javobni yoddan aytish malakasi ortdi','Faqat o‘qituvchi gapini qaytarish jarayoni davom etdi','Faqat topshiriqning tashqi shakli eslab qolindi','Yangi vaziyatga tatbiq qilish bilimni qo‘llashni bildiradi','qollash'),
(1,4,'Ta’lim va rivojlanish o‘rtasidagi munosabat qaysi javobda to‘g‘ri?','Ta’lim rivojlanishga ta’sir qiladi va imkoniyatlarga tayangan holda quriladi','Ta’lim rivojlanishdan butunlay mustaqil va o‘zgarmas jarayondir','Rivojlanish bilimdan ajralgan faqat jismoniy o‘zgarishdir','Rivojlanish o‘qituvchiga bog‘liq emas va hisobga olinmaydi','Ta’lim yosh va rivojlanish imkoniyatlarini inobatga oladi','bilish'),
(1,5,'Kichik yoshdagi o‘quvchilar mavhum qoidani anglamadi. Dastlab nima ma’qul?','Yoshga mos konkret namuna va ketma-ket izohdan foydalanish','Qoidani o‘sha shaklda yanada tez va ko‘proq takrorlash','Tushunmagan bolalarni sinfdan alohida chiqarib yuborish','Shu mavzu bo‘yicha barcha mashqlarni birdan bekor qilish','Yosh psixologiyasi o‘quvchining anglash imkoniyatini hisobga oladi','qollash'),
(1,6,'O‘quvchi vazifani tushunmadi, biroq uni dangasa deb atashdi. To‘g‘ri yondashuv?','Avval tayanch bilim, topshiriq murakkabligi va motivatsiyani tekshirish','Avval javobini tinglamasdan past baho bilan cheklanish','Avval sinf oldida xatti-harakatini tanqid qilish','Avval barcha bolalarga bir xil murakkab vazifa berish','Pedagogik xulosa individual va ta’limiy omillar tahliliga tayanishi kerak','mulohaza'),
(1,7,'O‘quvchida tabiatni asrash odatini shakllantirish nimaga ko‘proq taalluqli?','Ekologik tarbiyaga — mas’uliyatli munosabatni tarbiyalashga','Didaktik nazoratga — faqat baholarni qayd etishga','Texnik rejalashga — faqat dars vaqtini taqsimlashga','Psixologik testga — faqat xotirani o‘lchashga','Tarbiya munosabat va xulqning shakllanishiga qaratiladi','qollash'),
(1,8,'Pedagogik mahoratni faqat fan bilimiga tenglashtirish nega noto‘g‘ri?','Muloqot, qobiliyat va pedagogik texnikani ham talab etadi','Fan bilimini umuman kerak emas deb hisoblashni talab etadi','O‘qituvchining har bir ishini faqat bahoga bog‘lashni talab etadi','Barcha darslarda bir xil metoddan foydalanishni talab etadi','Pedagogik mahorat o‘zaro bog‘liq bir necha kasbiy tarkibdan iborat','mulohaza'),
(1,9,'O‘qituvchi bolaning e’tibori susayganini sezdi. Qaysi qobiliyat namoyon bo‘ldi?','Perseptiv qobiliyat — o‘quvchi holatini sezish va tushunish','Akademik qobiliyat — mavzuga oid ilmiy bilimni kengaytirish','Tashkilotchilik qobiliyati — tadbir ishlarini muvofiqlashtirish','Nutq qobiliyati — tushunchani ravon va aniq bayon qilish','Perseptiv qobiliyat boshqa odamning ichki holatini anglashga yordam beradi','qollash'),
(1,10,'Yosh psixologiyasini amalda hisobga olishning to‘g‘ri belgisi qaysi?','Dars vazifasini yosh, rivojlanish va tayanch tajribaga moslash','Barcha yoshdagilarga bir xil ko‘rsatma va vaqt belgilash','Faqat tug‘ilgan yiliga qarab bolaga qat’iy baho qo‘yish','Sinf darajasidan qat’i nazar bir xil terminlarni berish','Vazifa yosh imkoniyatlariga mos bo‘lishi kerak','qollash'),
(1,11,'O‘quvchi atamani takrorlaydi, ammo misol keltira olmaydi. Nima tekshiriladi?','Tushunchaning mazmuniy o‘zlashtirilishi va qo‘llanilishi','Faqat o‘quvchining yozuv tezligi va daftar muqovasi','Faqat sinfdagi tashkiliy tartib va o‘tirish joyi','Faqat uy vazifasi topshirilgan vaqt va imzo','Eslab qolish tushunish va qo‘llash bilan aynan teng emas','mulohaza'),
(1,12,'O‘qituvchi ovoz, mimika va imo-ishorani o‘rinli boshqardi. Bu nimaga misol?','Pedagogik texnikaga — muloqot vositalarini boshqarishga','Didaktikaga — faqat dars mazmunini tanlashga','Maktabshunoslikka — muassasa rejasini yuritishga','Yosh psixologiyasiga — rivojlanish davrini tasniflashga','Ovoz, mimika va jest pedagogik texnikaning tarkibiga kiradi','qollash'),
(2,1,'Bir nechta kuzatuvdan umumiy qoida keltirib chiqarildi. Bu qaysi yo‘l?','Induksiya — xususiy kuzatuvlardan umumiy xulosaga kelish','Deduksiya — umumiy qoidadan xususiy holatni chiqarish','Analogiya — o‘xshashlikka tayangan taxminni ilgari surish','Modellashtirish — obyektning shartli nusxasini qurish','Induksiya xususiydan umumiyga yo‘naladi','bilish'),
(2,2,'Umumiy teorema aniq bir masalaga tatbiq etildi. Bu qaysi yo‘l?','Deduksiya — umumiy qoidadan xususiy holatga o‘tish','Induksiya — alohida faktlardan umumiy xulosaga o‘tish','Analogiya — o‘xshash belgidan taxminiy xulosa qilish','Eksperiment — nazoratli sharoitda hodisani sinash','Deduksiyada umumiy hukm asosida xususiy natija chiqariladi','bilish'),
(2,3,'O‘xshash ikki tajribadan birida natija taxmin qilindi. Xulosa maqomi qanday?','Analogiyaga asoslangan va qo‘shimcha tekshiruv talab etadigan taxmin','Induksiyaga asoslangan va barcha sharoitda qat’iy isbot','Deduksiyaga asoslangan va istisnosiz umumiy qonun','Nazoratga asoslangan va barcha dalillardan mustaqil baho','Analogiya o‘xshashlikdan taxmin chiqaradi, isbotni almashtirmaydi','mulohaza'),
(2,4,'O‘qituvchi formulani o‘rgatib xarid hisobiga qo‘llatdi. Qaysi tamoyil?','Nazariya bilan amaliyot birligi tamoyili amalga oshdi','Ilmiylikni faqat atama yodlash deb tushunish yuz berdi','Tizimlilikni faqat daftar yuritish deb tushunish yuz berdi','Ko‘rgazmalilikni maqsadsiz namoyish qilish yuz berdi','Nazariy bilim real faoliyatda qo‘llanmoqda','qollash'),
(2,5,'Darsda yangi bilim avvalgi tushunchalardan uzilib berildi. Nima zarar ko‘rdi?','Tizimlilik va izchillik — mazmunning mantiqiy bog‘lanishi','Ko‘rgazmalilik — mavzuning tasvir bilan boyitilishi','Mustahkamlik — ma’lumotni qayta mashq orqali saqlash','Ilmiylik — xulosani tekshirilgan dalilga asoslash','Yangi bilim avvalgi bilimga izchil ulanadi','mulohaza'),
(2,6,'Bir mavzuga turli tayyorgarlikdagi o‘quvchilarga mos vazifa berildi. Bu qaysi tamoyil?','Individuallashtirish — vazifani o‘quvchi imkoniyatiga moslash','Ilmiylik — ma’lumotning asoslangan faktlarga tayanishi','Mustahkamlik — bilimlarni takrorlab saqlab qolish','Ko‘rgazmalilik — tasvir va model yordamida anglash','Individual yondashish ehtiyoj va tayyorgarlikni hisobga oladi','qollash'),
(2,7,'Tajriba o‘rniga tekshirilmagan mish-mish fakt sifatida o‘qitildi. Qaysi tamoyil buzildi?','Ilmiylik — ma’lumotning tekshirilgan va asosli bo‘lishi','Onglilik — o‘quvchining faol va tushunib qatnashishi','Individuallashtirish — vazifaning o‘quvchiga mos bo‘lishi','Mustahkamlik — bilimning uzoq vaqt yodda qolishi','Ilmiylik tasdiqlanmagan fikrni fakt deb berishni rad etadi','qollash'),
(2,8,'O‘quvchi sxemani ko‘rdi, lekin fikr yuritmadi. Nima kuchaytirilishi lozim?','Onglilik va faollik — mustaqil tahlil hamda izohlash','Ko‘rgazmalilik — faqat tasvirlar sonini ko‘paytirish','Tizimlilik — faqat mashg‘ulot jadvalini uzaytirish','Mustahkamlik — faqat ta’rifni ko‘chirib yozdirish','Vizual vosita anglash va faoliyat bilan bog‘lanishi kerak','mulohaza'),
(2,9,'O‘quvchilar tushunchani bir oy o‘tib ham qo‘llay oldi. Bu qaysi tamoyil natijasi?','Mustahkamlik — bilim va ko‘nikmaning barqaror saqlanishi','Ilmiylik — tushuncha faqat kitobda yozilgan bo‘lishi','Ko‘rgazmalilik — har safar bir xil slaydni qo‘llash','Individuallashtirish — barchaga aynan bir xil mashq','Bilim barqaror saqlanishi mustahkamlik natijasidir','bilish'),
(2,10,'Boshlang‘ich sinfga og‘ir ta’rif yoshga mos misolda tushuntirildi. Qaysi tamoyil?','Tushunarlilik — mazmunni yosh va tayyorgarlikka moslash','Ilmiylik — xulosa faqat ilmiy atamada berilishi','Mustahkamlik — material faqat yodlatib o‘rgatilishi','Muntazamlik — har gal bir xil dars rejasi qo‘llanishi','Tushunarli ta’lim o‘quvchi imkoniyatini inobatga oladi','qollash'),
(2,11,'Juda chiroyli video dars maqsadiga aloqasiz edi. Eng asosli xulosa?','Ko‘rgazmali vositaning tanlovi mazmun va maqsadga mos bo‘lishi kerak','Har qanday video borligi o‘zlashtirishni kafolatlashi kerak','Videoning davomiyligi yuqori bo‘lsa tushunish ham shart','Ranglarning ko‘pligi ilmiy asosdan ustun turishi kerak','Ko‘rgazmalilik vositasi pedagogik maqsadga xizmat qilishi lozim','mulohaza'),
(2,12,'Suhbatda o‘quvchi o‘z fikrini dalillab, savol berdi. Qaysi tamoyil ustun?','Onglilik va faollik — tushunib, faol fikrlash','Mustahkamlik — faqat javobni yodda saqlash','Ko‘rgazmalilik — faqat rasmni tomosha qilish','Individuallashtirish — faqat topshiriq sonini farqlash','Fikrni asoslash va savol berish ongli faollik belgisidir','qollash')
 ) t(topic_order,seed_no,stem,answer,wrong_1,wrong_2,wrong_3,explanation,cognitive)
 LOOP
  SELECT l.id INTO STRICT v_lesson FROM public.lessons l JOIN public.modules m ON m.id=l.module_id WHERE m.code='M15' AND l.order_idx=r.topic_order AND l.status='published';
  SELECT c.id,c.subject_id,c.group_code INTO STRICT v_con,v_sub,v_group FROM public.constructs c WHERE c.code='PM.GEN.'||lpad(r.topic_order::text,2,'0') AND c.is_active;
  v_seed := 'm15-y1-20261018:'||r.topic_order::text||':'||r.seed_no::text;
  v_qid := md5(v_seed)::uuid;
  INSERT INTO public.questions (id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,status,source_reference,source_lesson_id,is_generated)
  VALUES(v_qid,v_sub,v_con,v_group,'Y1'::public.question_format,r.cognitive::public.cognitive_level,3,r.stem,'review'::public.content_status,'authored:m15-topictest-20261018:'||r.topic_order::text||':'||r.seed_no::text,v_lesson,false)
  ON CONFLICT (id) DO NOTHING;
  v_choices := ARRAY[r.answer,r.wrong_1,r.wrong_2,r.wrong_3];
  FOR v_n IN 1..4 LOOP
    v_oid := md5(v_seed||':option:'||v_n::text)::uuid;
    INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(v_oid,v_qid,'a',v_n,v_choices[v_n]) ON CONFLICT(id) DO NOTHING;
  END LOOP;
  INSERT INTO public.question_keys(question_id,payload,explanation_md)
  VALUES(v_qid,jsonb_build_object('correct_option_id',md5(v_seed||':option:1')::uuid),r.explanation)
  ON CONFLICT(question_id) DO NOTHING;
 END LOOP;
END
$m15$;
COMMIT;
